"""Independent regressions for the Phase 1 review findings; synthetic data only."""
from itertools import permutations, product
import struct

import numpy as np
import pyvista as pv
import pytest

from test_lambda_ci_workflow import synthetic_file
from test_vortex_3d import run_args
from nek_post.io_nek import read_nek_file
from nek_post.hex_validation import validate_hexahedral_grid
from nek_post.vortex_3d import write_binary_vtu
from nek_post.vortex_3d_workflow import run_single_frame_vortex


def file_with_map(tmp_path, ids, *, endian='little'):
    """Change only newly generated bytes, not the geometry/velocity record order."""
    _, source = synthetic_file(tmp_path)
    if endian == 'big':
        from pymech.neksuite import writenek
        data = read_nek_file(source)
        data.endian = 'big'
        case = tmp_path/'big_original'
        case.mkdir()
        source = case/source.name
        writenek(str(source), data)
    original = source.read_bytes()
    prefix = '<' if endian == 'little' else '>'
    assert struct.unpack(prefix+'2i', original[136:144]) == (1, 2)
    case = tmp_path/'modified_map'
    case.mkdir()
    target = case/source.name
    target.write_bytes(original[:136] + struct.pack(prefix+f'{len(ids)}i', *ids) + original[144:])
    return case, target


@pytest.mark.parametrize('endian', ['little', 'big'])
@pytest.mark.parametrize('ids', [(0, 0), (0, 2), (1, 1), (2, 2), (-1, 2), (1, 3)])
def test_raw_invalid_map_stops_before_reader_and_computation(tmp_path, monkeypatch, ids, endian):
    import nek_post.vortex_3d_workflow as module
    case, source = file_with_map(tmp_path, ids, endian=endian)
    original = source.read_bytes()
    monkeypatch.setattr(module, 'read_nek_file', lambda *a, **k: pytest.fail('invalid map reached reader'))
    monkeypatch.setattr(module, 'compute_native_vortex_fields', lambda *a, **k: pytest.fail('invalid map reached scientific calculation'))
    with pytest.raises(ValueError, match='[Ee]lement map'):
        run_single_frame_vortex(**run_args(case, tmp_path/'out'))
    assert source.read_bytes() == original
    assert not (tmp_path/'out').exists()


def test_pymech_zero_map_fallback_is_not_accepted(tmp_path):
    case, source = file_with_map(tmp_path, (0, 0))
    # Confirm the installed reader really accepts this damaged map and returns
    # finite sequential geometry. Workflow rejection must precede that fallback.
    fallback = read_nek_file(source)
    np.testing.assert_array_equal(fallback.elmap, (0, 0))
    assert all(np.isfinite(e.pos).all() for e in fallback.elem)
    with pytest.raises(ValueError, match='[Ee]lement map'):
        run_single_frame_vortex(**run_args(case, tmp_path/'out'))
    assert not (tmp_path/'out').exists()


@pytest.mark.parametrize('endian', ['little', 'big'])
@pytest.mark.parametrize('word_bytes', [4, 8])
def test_nontrivial_one_based_map_preserves_physical_fields_and_reader_order(tmp_path, endian, word_bytes):
    from pymech.neksuite import writenek
    _, source = synthetic_file(tmp_path)
    data = read_nek_file(source)
    for ei, element in enumerate(data.elem):
        x, y, z = element.pos
        rate = 1.25 if ei == 0 else -2.5
        element.vel[:] = np.stack((.5*x, -rate*z, rate*y))
    case = tmp_path/'baseline_input'
    case.mkdir()
    writenek(str(case/source.name), data)
    data.elmap[:] = (2, 1)
    data.endian, data.wdsz = endian, word_bytes
    permuted = tmp_path/'permuted'
    permuted.mkdir()
    target = permuted/source.name
    writenek(str(target), data)
    decoded = read_nek_file(target)
    np.testing.assert_array_equal(decoded.elmap, (2, 1))
    for actual, expected in zip(decoded.elem, data.elem):
        np.testing.assert_array_equal(actual.pos, expected.pos)
        np.testing.assert_array_equal(actual.vel, expected.vel)
    before = target.read_bytes()
    a = run_single_frame_vortex(**run_args(case, tmp_path/'baseline'))
    b = run_single_frame_vortex(**run_args(permuted, tmp_path/'actual'))
    ga, gb = (pv.read(r['output_paths']['vtu']) for r in (a, b))
    np.testing.assert_array_equal(ga.points, gb.points)
    np.testing.assert_array_equal(ga.cells, gb.cells)
    for name in ('omega_x', 'lambda_ci'):
        np.testing.assert_array_equal(ga[name], gb[name])
        assert np.ptp(ga[name]) > .5  # Both fields distinguish the elements.
    assert b['input_word_bytes'] == word_bytes
    assert b['element_map']['reader_element_order'] == 'ascending global ID; data.elem[ID-1]'
    assert a['element_map']['file_order_ids_sha256'] != b['element_map']['file_order_ids_sha256']
    assert target.read_bytes() == before


@pytest.mark.parametrize('remaining', [b'', b'\x01\x00', struct.pack('<i', 1)])
def test_truncated_or_missing_raw_map_rejected(tmp_path, monkeypatch, remaining):
    import nek_post.vortex_3d_workflow as module
    _, source = synthetic_file(tmp_path)
    case = tmp_path/'truncated'
    case.mkdir()
    (case/source.name).write_bytes(source.read_bytes()[:136] + remaining)
    monkeypatch.setattr(module, 'read_nek_file', lambda *a, **k: pytest.fail('truncated map reached reader'))
    with pytest.raises(ValueError, match='Element map'):
        run_single_frame_vortex(**run_args(case, tmp_path/'out'))
    assert not (tmp_path/'out').exists()


@pytest.mark.parametrize('retained_map', [(0, 0), (1, 1), (2, 1)])
def test_changed_reader_map_rejected_before_computation(tmp_path, monkeypatch, retained_map):
    import nek_post.vortex_3d_workflow as module
    case, _ = synthetic_file(tmp_path)
    original_reader = module.read_nek_file
    def altered(*args, **kwargs):
        data = original_reader(*args, **kwargs)
        data.elmap[:] = retained_map
        return data
    monkeypatch.setattr(module, 'read_nek_file', altered)
    monkeypatch.setattr(module, 'compute_native_vortex_fields', lambda *a, **k: pytest.fail('bad reader map reached computation'))
    with pytest.raises(ValueError, match='Element map'):
        run_single_frame_vortex(**run_args(case, tmp_path/'out'))
    assert not (tmp_path/'out').exists()


