@pytest.mark.parametrize('kind', ['connectivity', 'offsets'])
def test_native_topology_roundtrip_detects_changed_ids_and_offsets(tmp_path, monkeypatch, kind):
    ids = np.arange(8)
    grid = pv.UnstructuredGrid(np.r_[8, ids, 8, ids], np.full(2, pv.CellType.HEXAHEDRON, dtype=np.uint8), CORNERS.copy())
    grid['omega_x'] = np.zeros(8, dtype=np.float64)
    grid['lambda_ci'] = np.ones(8, dtype=np.float64)
    original = pv.UnstructuredGrid.save
    def corrupt(self, path, **kwargs):
        if kind == 'offsets': packed = np.r_[7, ids[:7], 9, ids[7:], ids]
        else: packed = np.r_[8, 1, ids[1:], 8, ids]
        changed = pv.UnstructuredGrid(packed, self.celltypes.copy(), self.points.copy())
        for name, values in self.point_data.items(): changed.point_data[name] = values.copy()
        for name, values in self.field_data.items(): changed.field_data[name] = values.copy()
        original(changed, path, **kwargs)
    monkeypatch.setattr(pv.UnstructuredGrid, 'save', corrupt)
    with pytest.raises(ValueError, match=f'round-trip changed {kind}'):
        write_binary_vtu(tmp_path/'corrupt.vtu', grid, time=0.)
